import{Q as e,X as t,ft as n,n as r}from"./chunks/framework.COFTIYvu.js";var i=JSON.parse(`{"title":"Running with Bento","description":"","frontmatter":{"id":"guide.running-with-bento","title":"Running with Bento","describes":["proposal.0001","proposal.0002","proposal.0003"]},"headers":[],"relativePath":"guides/running-with-bento.md","filePath":"guides/running-with-bento.md"}`),a={name:`guides/running-with-bento.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="running-with-bento" tabindex="-1">Running with Bento <a class="header-anchor" href="#running-with-bento" aria-label="Permalink to “Running with Bento”">​</a></h1><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to “What it does”">​</a></h2><p>The <code>bento</code> command runs your project. <code>bento run</code> starts a JavaScript, TypeScript, JSX, or TSX source file, or a task declared in the top-level <code>tasks</code> field of <code>package.json</code>. <code>bento install</code> installs the project&#39;s dependencies through its declared pnpm toolchain.</p><p>A <code>bento run</code> command without permission flags is unrestricted, as <code>node</code> is: the code it runs can do anything your user can. Running code you do not trust requires <code>--permission</code>, which restricts the launch to what its <code>--allow-*</code> flags allow. <a href="#control-what-code-may-do">Control what code may do</a> lists the flags.</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>bento run [--permission] [--allow-*]... [--watch] &lt;script-path | task-name&gt; [args...]</span></span>
<span class="line"><span>bento install [--frozen-lockfile]</span></span></code></pre></div><p>Bento options go before the target. Everything after the target belongs to the script or task.</p><h2 id="how-to-use-it" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it" aria-label="Permalink to “How to use it”">​</a></h2><h3 id="get-bento" tabindex="-1">Get Bento <a class="header-anchor" href="#get-bento" aria-label="Permalink to “Get Bento”">​</a></h3><p>Bento is built from this repository for macOS on Apple silicon. The default CLI build includes the local Prompt API backend and requires macOS 27.0 or newer and Xcode with SDK 27 or newer. Building also needs the Rust toolchain pinned in <code>rust-toolchain.toml</code>, which <code>rustup</code> selects automatically. From the repository root:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">cargo</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> install</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --locked</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --path</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> crates/bento_cli</span></span></code></pre></div><p>This installs the <code>bento</code> executable into Cargo&#39;s bin directory (<code>~/.cargo/bin</code> by default). Running an installed project needs nothing else. Installing dependencies needs pnpm and Node, because <code>bento install</code> delegates to the project&#39;s declared pnpm, and the package tools a task runs, such as <code>oxfmt</code>, <code>tsc</code>, or <code>remix db migrate</code>, start through their own executables, which may be Node scripts.</p><p>Use <code>cargo install --locked --path crates/bento_cli --no-default-features</code> for a backend-free build without the new Foundation Models SDK requirement. The JavaScript <code>LanguageModel</code> API remains present but unavailable. See <a href="./prompt-api">Using the Prompt API</a> for model readiness, permissions, and Rust reuse.</p><h3 id="choose-what-to-run" tabindex="-1">Choose what to run <a class="header-anchor" href="#choose-what-to-run" aria-label="Permalink to “Choose what to run”">​</a></h3><p>Bento decides whether the target is a file or a task:</p><ul><li>A target containing <code>/</code> is a file: <code>bento run ./server.ts</code>, <code>bento run scripts/seed.ts</code>.</li><li>A target with a file extension is a file when that file exists: <code>bento run server.ts</code>.</li><li>Otherwise a task with exactly that name wins, even over a file of the same name.</li><li>Anything else is an error that names the target. Bento never runs it as a shell command.</li></ul><p>A task&#39;s project is the nearest directory, from the current one upward, that holds a <code>package.json</code>. A script&#39;s project is the nearest one from the script&#39;s own directory upward. <a href="./tasks-and-environment">Tasks and Environment</a> explains how tasks are declared, ordered, and run.</p><h3 id="pass-arguments" tabindex="-1">Pass arguments <a class="header-anchor" href="#pass-arguments" aria-label="Permalink to “Pass arguments”">​</a></h3><p>Words after a script path are the script&#39;s own arguments, passed through unchanged: <code>bento run server.ts --port 3000</code>.</p><p>Arguments for a task go after <code>--</code>, and Bento appends them, shell-quoted, to the task&#39;s own command: <code>bento run test -- --reporter &quot;dot matrix&quot;</code>. Dependencies never receive them. Bento rejects task arguments without the <code>--</code>, so a misplaced option such as <code>bento run dev --watch</code> fails instead of being passed on silently. A task that has only <code>dependsOn</code>, or an array of commands, has no single command to receive arguments, so it rejects them too. In each case Bento says why and runs nothing.</p><h3 id="control-what-code-may-do" tabindex="-1">Control what code may do <a class="header-anchor" href="#control-what-code-may-do" aria-label="Permalink to “Control what code may do”">​</a></h3><p>Without <code>--permission</code>, a launch is unrestricted. The code can read and write any file your user can, connect and listen anywhere, see the whole prepared environment, start subprocesses and workers, load native addons, and use the local language model when the build includes it. That is Node&#39;s default, and it is what your own project&#39;s tools expect: <code>bento run node_modules/vite/bin/vite.js build</code> needs no flags. Never run code you do not trust this way.</p><p><code>--permission</code>, given before the target, makes the launch restricted. The code then holds only the permissions its <code>--allow-*</code> flags give it, and everything else is denied:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>bento run [--permission] [--allow-fs-read=PATH]... [--allow-fs-write=PATH]... [--allow-env=NAME]...</span></span>
<span class="line"><span>          [--allow-net] [--allow-child-process] [--allow-worker] [--allow-addons] [--allow-wasi]</span></span>
<span class="line"><span>          [--allow-ffi] [--allow-inspector] [--allow-openssl-store] [--allow-fs-vfs]</span></span>
<span class="line"><span>          [--allow-language-model] [--watch] &lt;script-path | task-name&gt; [args...]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Flag</th><th>Allows</th><th><code>process.permission.has()</code> scope</th></tr></thead><tbody><tr><td><code>--allow-fs-read=PATH</code></td><td>Reading files and directories</td><td><code>fs.read</code></td></tr><tr><td><code>--allow-fs-write=PATH</code></td><td>Creating, changing, and removing files</td><td><code>fs.write</code></td></tr><tr><td><code>--allow-env=NAME</code></td><td>Keeping environment variables</td><td><code>env</code></td></tr><tr><td><code>--allow-net</code></td><td>Connecting to and listening on any host and port</td><td><code>net</code></td></tr><tr><td><code>--allow-child-process</code></td><td>Starting subprocesses</td><td><code>child</code></td></tr><tr><td><code>--allow-worker</code></td><td>Starting worker threads</td><td><code>worker</code></td></tr><tr><td><code>--allow-addons</code></td><td>Loading native Node-API addons from any path</td><td><code>addon</code></td></tr><tr><td><code>--allow-wasi</code></td><td>WASI</td><td><code>wasi</code></td></tr><tr><td><code>--allow-ffi</code></td><td>FFI</td><td><code>ffi</code></td></tr><tr><td><code>--allow-inspector</code></td><td>The inspector</td><td><code>inspector</code></td></tr><tr><td><code>--allow-openssl-store</code></td><td>OpenSSL STORE loaders</td><td><code>openssl.store</code></td></tr><tr><td><code>--allow-fs-vfs</code></td><td>Mounting a virtual file system</td><td>none, as in Node</td></tr><tr><td><code>--allow-language-model</code></td><td>The local language model</td><td><code>language-model</code></td></tr></tbody></table><p>These are Node 26&#39;s flags, with Node&#39;s meanings. <code>--allow-language-model</code> is Bento&#39;s own, because Node has no language model.</p><p>The file <code>bento run</code> executes is readable without <code>--allow-fs-read</code>, and only that file: the modules it imports, including installed packages, need read permission. <code>bento run --permission server.ts</code> therefore loads <code>server.ts</code> and is denied its first import. Run from the project directory, <code>--allow-fs-read=.</code> covers the project&#39;s modules and its own <code>node_modules</code>.</p><p><code>--allow-wasi</code>, <code>--allow-ffi</code>, <code>--allow-inspector</code>, <code>--allow-openssl-store</code>, and <code>--allow-fs-vfs</code> are accepted, recorded, and reported by <code>process.permission.has()</code>. Where Bento provides the API one of them governs, the flag gates it with Node&#39;s error. Where Bento does not provide that API yet, the API fails with or without the flag.</p><h4 id="flag-syntax-and-errors" tabindex="-1">Flag syntax and errors <a class="header-anchor" href="#flag-syntax-and-errors" aria-label="Permalink to “Flag syntax and errors”">​</a></h4><ul><li><code>--allow-fs-read</code> and <code>--allow-fs-write</code> require a value, given as <code>--allow-fs-read=VALUE</code> or <code>--allow-fs-read VALUE</code>, and may be repeated. Without one, the launch fails with <code>error: --allow-fs-read requires an argument</code>.</li><li><code>--allow-env</code> takes <code>*</code>, a variable name, or a name prefix followed by <code>*</code>, such as <code>APP_*</code>. Values may be repeated or separated by commas, and an empty item between commas, as in <code>--allow-env=PORT,,HOST</code>, is skipped. Without a value, the launch fails with <code>error: --allow-env requires an argument</code>. An item of any other form, such as <code>A*B</code> or <code>A=B</code>, fails with <code>error: --allow-env must be &#39;*&#39;, a variable name, or a variable name prefix followed by &#39;*&#39;</code>.</li><li>Every other flag takes no value. Giving one a value, such as <code>127.0.0.1:3000</code> for <code>--allow-net</code>, is a usage error that names the flag. Node accepts such a value and ignores it, allowing every host; Bento refuses it, so a command written for an earlier Bento&#39;s host-scoped network flag cannot silently allow every host.</li><li>Any <code>--allow-*</code> flag without <code>--permission</code> fails before anything runs, with <code>error: --permission is required</code>.</li><li>These errors exit with status 1, like Bento&#39;s other usage errors. Node exits with status 9 when a flag is missing its value.</li><li><code>bento run --help</code> lists the flags under a &quot;Permissions&quot; heading.</li></ul><p>Quote a value containing <code>*</code> in your shell, as in <code>--allow-fs-read=&#39;*&#39;</code>, so that the shell hands it to Bento unchanged. Unquoted, zsh refuses the command because no file matches the pattern.</p><h4 id="which-paths-a-value-covers" tabindex="-1">Which paths a value covers <a class="header-anchor" href="#which-paths-a-value-covers" aria-label="Permalink to “Which paths a value covers”">​</a></h4><ul><li><code>*</code> alone covers every path.</li><li>Any other value is a path, absolute or relative to the directory you run <code>bento</code> in, not to the project root.</li><li>A value containing <code>*</code> covers every path whose text begins with the text before the first <code>*</code>. Anything after that <code>*</code> is ignored. <code>--allow-fs-read=&#39;./test*&#39;</code> covers <code>test</code>, <code>test2</code>, and <code>testing/notes.txt</code>, but not <code>tes</code>.</li><li>Without <code>*</code>, an existing directory covers itself and everything beneath it. Anything else, a file or a path that does not exist yet, covers exactly that path. A directory the code will create needs a trailing <code>*</code>: <code>--allow-fs-write=&#39;./build/*&#39;</code> covers <code>build</code> itself and everything the code creates beneath it.</li><li>A comma is part of the path. To allow several paths, repeat the flag. When a value contains a comma, Bento prints Node&#39;s warning to standard error, naming the flag, and continues:</li></ul><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>warning: The --allow-fs-read CLI flag has changed. Passing a comma-separated list of paths is no longer valid. Documentation can be found at https://nodejs.org/api/permissions.html#file-system-permissions</span></span></code></pre></div><p>Bento compares paths at their real locations. It resolves each value as the operating system would before comparing it: when <code>data</code> is a link to <code>/srv/data</code>, <code>--allow-fs-read=./data</code> covers <code>/srv/data</code>, and because <code>..</code> after a link leaves the link&#39;s target, <code>--allow-fs-read=./data/../shared</code> covers <code>/srv/shared</code>. A link to something that does not exist yet names the location it points to, and a path that does not exist yet keeps its missing part as written beneath its nearest existing directory. A value with <code>*</code> has its existing directory part resolved and the rest kept as written. On macOS, where <code>/tmp</code> is a link to <code>/private/tmp</code>, <code>--allow-fs-read=/tmp/app</code> covers <code>/private/tmp/app</code>.</p><p>Operations that follow links are checked against the fully resolved target, so a link inside an allowed directory that points outside it is denied. Node compares paths as written and follows such a link. Operations on a link itself, such as <code>lstat</code>, <code>readlink</code>, and <code>unlink</code>, are checked at the link&#39;s own location, as <a href="./node-compatibility#permissions-and-native-code">Node Compatibility</a> describes. Creating a symbolic link requires both <code>--allow-fs-read=&#39;*&#39;</code> and <code>--allow-fs-write=&#39;*&#39;</code>, because a permission for particular paths cannot vouch for a target that is resolved later.</p><h4 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to “Environment variables”">​</a></h4><p>An unrestricted launch sees the whole prepared environment. A restricted launch starts with every variable that <code>--allow-env</code> does not match removed, except the variables Node always keeps, such as <code>PATH</code> and <code>HOME</code>, and the values Bento prepared for the launch: those from the project&#39;s environment files and the watch-mode <code>NODE_ENV</code> default. Reading a removed variable returns <code>undefined</code> and warns the first time. The code may still set, change, and delete any variable while it runs. <a href="./tasks-and-environment#environment-in-a-restricted-launch">Tasks and Environment</a> gives the full rules.</p><h4 id="subprocesses-workers-native-addons-and-the-network" tabindex="-1">Subprocesses, workers, native addons, and the network <a class="header-anchor" href="#subprocesses-workers-native-addons-and-the-network" aria-label="Permalink to “Subprocesses, workers, native addons, and the network”">​</a></h4><p><code>node:child_process</code> (<code>spawn</code>, <code>exec</code>, <code>execFile</code>, <code>fork</code>, and their synchronous forms) and <code>Deno.Command</code> work in an unrestricted launch, and in a restricted one with <code>--allow-child-process</code>. A child process runs with your user&#39;s full authority, and no permission restricts it, so allowing child processes in a restricted launch lets the code escape every other restriction. Pass <code>--allow-child-process</code> only for code you would also run unrestricted. A subprocess receives the launch&#39;s environment after the startup removal. When a restricted launch starts a process, Bento also adds <code>BENTO_PERMISSION_CEILING</code> to that environment, describing the launch&#39;s permissions at that moment, so a <code>bento</code> the process starts stays within them, as <a href="#nested-bento-commands-stay-within-a-ceiling">nested launches</a> do. Bento does not change <code>NODE_OPTIONS</code>, and programs other than <code>bento</code> ignore the ceiling.</p><p><code>process.execPath</code> is the <code>bento</code> executable, and Bento does not accept Node&#39;s command-line options yet (<a href="https://github.com/bento-js/bento/issues/260" target="_blank" rel="noreferrer">#260</a>). <code>fork()</code>, and any code that starts <code>process.execPath</code> with Node&#39;s options, therefore fails with Bento&#39;s usage error from the child, even in an unrestricted launch.</p><p><code>worker_threads.Worker</code> and the Web <code>Worker</code> work in an unrestricted launch, and in a restricted one with <code>--allow-worker</code>. A worker always has its creator&#39;s current permissions; passing <code>execArgv</code> cannot change them.</p><p>Native addons load in an unrestricted launch, and in a restricted one with <code>--allow-addons</code>, from any path. An addon runs native code inside the <code>bento</code> process, outside every permission: once loaded, it is not contained by the file, network, or environment restrictions. Pass <code>--allow-addons</code> only when you trust every package that ships an addon.</p><p><code>--allow-net</code> allows every host and port. Neither Bento nor Node can limit a launch to particular hosts.</p><h4 id="available-in-every-launch-and-in-none" tabindex="-1">Available in every launch, and in none <a class="header-anchor" href="#available-in-every-launch-and-in-none" aria-label="Permalink to “Available in every launch, and in none”">​</a></h4><p>System information is available in every launch, restricted or not, because Node restricts none of it: <code>os.homedir()</code>, <code>os.hostname()</code>, <code>os.userInfo()</code>, <code>os.networkInterfaces()</code>, <code>os.cpus()</code>, the memory, load, uptime, and release queries, and their <code>Deno</code> counterparts.</p><p>Some operations are unavailable in every launch, because they are not permissions: importing remote modules, changing the <code>bento</code> process&#39;s working directory or loading an environment file into it (<code>process.chdir</code>, <code>process.loadEnvFile</code>), and terminating or signalling the <code>bento</code> process (<code>process.abort</code>, <code>process.kill</code>, <code>Deno.kill</code>). Code that starts a subprocess can still signal it with <code>subprocess.kill()</code>.</p><h4 id="denied-operations" tabindex="-1">Denied operations <a class="header-anchor" href="#denied-operations" aria-label="Permalink to “Denied operations”">​</a></h4><p>In a restricted launch, a denied operation throws what Node 26 throws for the same operation:</p><table tabindex="0"><thead><tr><th>Denied operation</th><th>What the code receives</th></tr></thead><tbody><tr><td>Reading a file</td><td><code>ERR_ACCESS_DENIED</code> with <code>permission: &#39;FileSystemRead&#39;</code> and <code>resource</code> set to the path as the call named it</td></tr><tr><td>Writing a file</td><td><code>ERR_ACCESS_DENIED</code> with <code>permission: &#39;FileSystemWrite&#39;</code> and the path as <code>resource</code></td></tr><tr><td>Connecting or listening</td><td><code>ERR_ACCESS_DENIED</code> with <code>permission: &#39;Net&#39;</code>; a denied <code>fetch</code> rejects with an error whose <code>cause</code> is that error</td></tr><tr><td>Starting a subprocess</td><td><code>ERR_ACCESS_DENIED</code> with <code>permission: &#39;ChildProcess&#39;</code> and the command as <code>resource</code>; no process starts</td></tr><tr><td>Starting a worker</td><td><code>ERR_ACCESS_DENIED</code> with <code>permission: &#39;WorkerThreads&#39;</code></td></tr><tr><td>Loading a native addon</td><td><code>ERR_DLOPEN_DISABLED</code>: <code>Cannot load native addon because loading addons is disabled.</code> The addon&#39;s native code never runs.</td></tr><tr><td>Using the language model</td><td><code>LanguageModel.availability()</code> reports <code>unavailable</code>, and <code>LanguageModel.create()</code> rejects with <code>NotAllowedError</code></td></tr><tr><td>Reading a removed environment variable</td><td>No error: the value is <code>undefined</code></td></tr></tbody></table><p>An <code>ERR_ACCESS_DENIED</code> message names the flag that would allow the operation, as in <code>Access to this API has been restricted. Use --allow-fs-read to manage permissions.</code> <code>Deno</code> namespace APIs throw the same errors as their Node counterparts.</p><p>An uncaught denial ends the run as a permission failure: Bento shows where the operation was denied, as <a href="#read-error-reports">Read error reports</a> describes, and exits with status 1.</p><p>Bento prints none of Node&#39;s <code>ExperimentalWarning</code> or <code>SecurityWarning</code> messages about permission flags; those describe Node&#39;s own stability levels. It keeps the comma warning above and the removed-variable warning, because each explains an outcome.</p><h4 id="inspect-and-drop-permissions" tabindex="-1">Inspect and drop permissions <a class="header-anchor" href="#inspect-and-drop-permissions" aria-label="Permalink to “Inspect and drop permissions”">​</a></h4><p>In a restricted launch, <code>process.permission</code> reports what the code holds and lets it give permissions up. In an unrestricted launch it is <code>undefined</code>, as in Node. <code>process.permission.has(&quot;fs.read&quot;, &quot;./data&quot;)</code> answers for one path, and <code>process.permission.has(&quot;fs.read&quot;)</code> is <code>true</code> only after <code>--allow-fs-read=&#39;*&#39;</code>. <code>process.permission.drop(&quot;fs.write&quot;)</code> removes a permission for the rest of the run, and nothing gives it back. <a href="./node-compatibility#inspect-and-drop-permissions">Node Compatibility</a> describes both methods.</p><h4 id="move-from-earlier-flags" tabindex="-1">Move from earlier flags <a class="header-anchor" href="#move-from-earlier-flags" aria-label="Permalink to “Move from earlier flags”">​</a></h4><p>Earlier Bento releases denied everything by default and used Deno&#39;s flag names. Commands that use them fail until you rewrite them:</p><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>--allow-read</code> / <code>--allow-read=a,b</code></td><td><code>--permission --allow-fs-read=*</code> / <code>--permission --allow-fs-read=a --allow-fs-read=b</code></td></tr><tr><td><code>--allow-write=data</code></td><td><code>--permission --allow-fs-write=data</code> (add <code>/*</code> when <code>data</code> does not exist yet)</td></tr><tr><td><code>--allow-net</code> / <code>--allow-net=host:port</code></td><td><code>--permission --allow-net</code> (every host)</td></tr><tr><td><code>--allow-env=A,B</code></td><td><code>--permission --allow-env=A,B</code></td></tr><tr><td><code>--allow-addons</code> / <code>--allow-addons=path</code></td><td><code>--permission --allow-addons</code> (every path)</td></tr><tr><td><code>--allow-language-model</code> / <code>--allow-language-model=false</code></td><td><code>--permission --allow-language-model</code> / <code>--permission</code> without it</td></tr></tbody></table><p>The removed flags are reported as unknown or malformed options. A command that passed no flags used to deny everything and now runs unrestricted, so add <code>--permission</code> wherever you relied on it to contain code. A nested launch that passes <code>--permission</code> no longer inherits the permissions its flags leave out. In a restricted launch, variables that <code>--allow-env</code> does not match are removed rather than hidden, writes to any variable succeed, and values from the project&#39;s environment files are visible. Code that checked for <code>NotCapable</code> or <code>PermissionDenied</code> errors must check for <code>ERR_ACCESS_DENIED</code> and <code>ERR_DLOPEN_DISABLED</code> instead.</p><h3 id="nested-bento-commands-stay-within-a-ceiling" tabindex="-1">Nested <code>bento</code> commands stay within a ceiling <a class="header-anchor" href="#nested-bento-commands-stay-within-a-ceiling" aria-label="Permalink to “Nested bento commands stay within a ceiling”">​</a></h3><p>When a task command runs <code>bento</code> again, the nested launch receives the permissions of the launch that started the task through <code>BENTO_PERMISSION_CEILING</code>. A process that a restricted guest starts receives that guest&#39;s permissions the same way. The name <code>bento</code> in a task command always means that same running <code>bento</code> executable, even when the project installs its own <code>bento</code> in <code>node_modules/.bin</code>, because Bento puts a link to itself first on the task&#39;s <code>PATH</code>.</p><ul><li>A nested launch without <code>--permission</code> holds exactly its ceiling&#39;s permissions: it is unrestricted under an unrestricted ceiling, and restricted the same way under a restricted one.</li><li>A nested launch with <code>--permission</code> holds exactly what its own flags and its entrypoint allow, as a launch from your shell does. Permissions its flags do not mention are denied, even when the ceiling holds them.</li><li>Each flag of a nested launch must fit within the ceiling. A flag that asks for more fails before any guest code runs, with an error that names the flag and the inherited limit, and the task that ran the nested command fails with it.</li><li>A nested launch&#39;s entrypoint is readable without a flag only when the ceiling&#39;s read permission covers it.</li></ul><p>A launch started directly from your shell has no ceiling. A nested launch can never widen the permissions it inherited.</p><h3 id="load-the-environment" tabindex="-1">Load the environment <a class="header-anchor" href="#load-the-environment" aria-label="Permalink to “Load the environment”">​</a></h3><p>Before running a script or task, Bento loads the project&#39;s <code>.env</code>, <code>.env.&lt;mode&gt;</code>, and <code>.env.local</code> files beneath the variables you set yourself. The mode comes from your <code>NODE_ENV</code>, else the <code>NODE_ENV</code> in <code>.env</code>; <code>bento run --watch</code> defaults it to <code>development</code> when neither sets it. <a href="./tasks-and-environment">Tasks and Environment</a> describes the file syntax, the precedence, and how nested launches choose their own mode file.</p><p>In a restricted launch, the values Bento loads from these files stay visible to the code even when <code>--allow-env</code> does not match them, as Node keeps the values from files named with <code>--env-file</code>. Task commands receive the whole prepared environment.</p><h3 id="run-a-script" tabindex="-1">Run a script <a class="header-anchor" href="#run-a-script" aria-label="Permalink to “Run a script”">​</a></h3><p><code>bento run server.mjs</code> executes the file in Bento&#39;s own runtime, inside the <code>bento</code> process. Nothing else needs to be installed to run it: Bento never starts Node, Deno, Bun, or pnpm, and runs the same with none of them on <code>PATH</code>.</p><p><code>bento run server.ts</code> executes TypeScript, JSX, and TSX directly. They need no build step, no prebuilt JavaScript entrypoint, and no <code>--import remix/node-tsx</code>, and Bento writes no JavaScript next to your sources: it transforms each module in memory as it loads. Bento follows the execution settings in <code>tsconfig.json</code> and the files it extends, such as <code>jsx</code> and <code>jsxImportSource</code>, and reports an execution-affecting setting it cannot honor rather than choosing another JSX runtime. It does not type-check; run your type checker as a task.</p><p>Modules resolve the way Node resolves them for the project: <code>package.json</code> <code>imports</code> and <code>exports</code>, ESM and CommonJS packages, and pnpm&#39;s <code>node_modules</code> layout. Packages resolve from the script&#39;s project even when you run <code>bento</code> from another directory. <code>tsconfig.json</code> <code>paths</code> never change resolution. Execution never installs or downloads anything; a missing package names the import that failed and points you to <code>bento install</code>.</p><p>An ESM import of a CommonJS source receives its <code>module.exports</code> value as the default export, including when that source re-exports JSON or a native addon through <code>require</code>. JSON fields and addon properties do not become inferred named exports.</p><p>The script sees what a Node script would see of its launch:</p><ul><li><code>process.argv.slice(2)</code> holds the words after the script path, unchanged, as under Node.</li><li><code>process.cwd()</code> is the directory you ran <code>bento</code> in, not the project root.</li><li><code>process.env</code> holds the prepared environment: your variables and the project&#39;s environment files. In a restricted launch, the variables removed at startup are absent from it.</li></ul><p>Packages with Node-API native addons, such as the compilers <code>remix/assets</code> uses, load into the <code>bento</code> process. A restricted launch needs <code>--allow-addons</code> for them; without it, loading an addon throws <code>ERR_DLOPEN_DISABLED</code> and its native code never runs.</p><p>An addon runs as native code in the <code>bento</code> process, so it sees the environment <code>bento</code> itself was started with, not the script&#39;s environment. The Oxc resolver that <code>remix/assets</code> loads honors <code>NODE_PATH</code> there: launched with <code>NODE_PATH</code> pointing at another project&#39;s packages, it can resolve packages outside your project, and a launch whose <code>--allow-fs-read</code> covers only the project is then denied reading them. Start <code>bento</code> without <code>NODE_PATH</code> set.</p><p>Top-level <code>await</code> works, and the script runs until it has no work left or calls <code>process.exit</code>. <code>process.exit(code)</code> ends the script with that exit code. When the script fails instead, Bento names the kind of failure: the script could not start, a module could not be resolved or transformed, permission was denied, or an exception went uncaught. It shows the error&#39;s message and where it happened, as <a href="#read-error-reports">Read error reports</a> describes, and <code>bento</code> exits with status 1.</p><p>A script that ends while work it started is still running does not finish the run yet. Bento cancels that work and waits five seconds for it to settle. When it has not settled by then, <code>bento</code> reports that the work the script started did not finish within the shutdown deadline and that disposal is incomplete, then exits with status 1, whatever the script&#39;s own exit code was.</p><h3 id="read-error-reports" tabindex="-1">Read error reports <a class="header-anchor" href="#read-error-reports" aria-label="Permalink to “Read error reports”">​</a></h3><p>When an error points at a place in a file Bento can read, Bento shows that place: the file with its line and column, the source lines around it, and a marker under the position saying what is wrong there. A <code>package.json</code> that is not valid JSON, for example, is reported like this:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>Error: /Users/you/guest-book/package.json is not valid JSON</span></span>
<span class="line"><span>   ╭─[ /Users/you/guest-book/package.json:4:3 ]</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span> 4 │   &quot;tasks&quot;: {}</span></span>
<span class="line"><span>   │   ┬</span></span>
<span class="line"><span>   │   ╰── expected \`,\` or \`}\`</span></span>
<span class="line"><span>───╯</span></span></code></pre></div><p>A script&#39;s failure is shown the same way when Bento knows where it happened: a syntax error, an uncaught exception, an import that cannot be resolved, or a denied operation. The place is in the source file as you wrote it, so a TypeScript or TSX error shows your TypeScript line, not the JavaScript Bento transformed it into. The marker says what happened there, such as <code>cannot be transformed here</code>, <code>thrown here</code>, <code>imported here</code>, or <code>denied here</code>. The stack trace and any errors that caused this one follow the quoted source:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>Error: uncaught exception: /Users/you/app/throw.ts: Uncaught (in promise) Error: no 42</span></span>
<span class="line"><span>   ╭─[ /Users/you/app/throw.ts:6:24 ]</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span> 6 │ const failure: Error = new Error(\`no \${answer}\`);</span></span>
<span class="line"><span>   │                        ┬</span></span>
<span class="line"><span>   │                        ╰── thrown here</span></span>
<span class="line"><span>───╯</span></span>
<span class="line"><span>    at file:///Users/you/app/throw.ts:6:24</span></span></code></pre></div><p><code>bento run --watch</code> reports a failed load or reload in the same form before it waits for the next change.</p><p>An error without such a place, or one whose file cannot be read, is a single line that starts with <code>error:</code>. Bento colors its reports only when standard error is a terminal, so redirected output and logs stay plain text, even where the runtime would style parts of an error message for your terminal.</p><p>Environment files are never shown, because their values are often secrets. An error in <code>.env</code> names the file and the line, as in <code>.env:2: quoted value is never closed</code>, and nothing of its contents.</p><h3 id="watch-for-changes" tabindex="-1">Watch for changes <a class="header-anchor" href="#watch-for-changes" aria-label="Permalink to “Watch for changes”">​</a></h3><p><code>bento run --watch server.ts</code> runs the script and restarts it completely when its source changes; it does not replace modules in place. Bento watches the project directory, so browser modules compiled by <code>remix/assets</code> count even though the server never imports them. It also watches non-dependency source files loaded outside the project through ESM imports, dynamic <code>import()</code>, CommonJS <code>require</code>, and <code>createRequire</code>, including calls made after startup. Bento adds those inputs within a fraction of a second. When it cannot watch one yet, it prints a warning once and keeps trying while the script runs.</p><p>Bento watches configuration that changes resolution and transformation: the project&#39;s <code>tsconfig.json</code> and its full <code>extends</code> chain, and the package scopes of loaded non-dependency sources. A workspace source&#39;s nearest existing <code>package.json</code> is watched even outside the project, so changing its <code>type</code>, <code>imports</code>, or self-reference <code>exports</code> restarts the run. Creating a nearer package scope inside the project or in an external source&#39;s own directory also restarts it. Creating <code>package.json</code> above an external source&#39;s own directory needs a manual restart. Watching an external package scope alone does not subscribe to its dependency or build-output subdirectories. Package-scope searches do not add watches above the project root. Bento reads <code>tsconfig.json</code> again on each change, so a file that an edit makes it extend is watched from that restart.</p><p>Edits, replacements, deletions, and creations that repair a missing file import trigger a restart. Failed resolution from a non-dependency source retains the missing file targets for ESM, CommonJS, dynamic <code>import()</code>, <code>require.resolve</code>, and <code>import.meta.resolve</code>, including targets named by non-dependency package <code>imports</code> and self-reference <code>exports</code>. A dependency&#39;s dynamic import adds no failed target merely because the application supplied the URL. If the application itself previously resolved that URL, including with <code>import.meta.resolve</code>, a later failed load retains the target. CommonJS missing-file candidates include extensions registered in <code>require.extensions</code>. Creating the missing parent directories and file recovers the run, including for workspace sources outside the project. An explicitly named failed path may require watching its nearest existing ancestor above the project root. Successful resolution discards its unused extension and index probes, even when a custom loader later throws a not-found error. CommonJS attribution uses the cached parent module object: requests with dependency or synthetic parents are excluded. Failed <code>createRequire</code> calls add no missing-file watches, even when anchored to a loaded application file, so repairs outside the watched project need a manual restart.</p><p>Creating a missing local script started through a Web Worker or <code>node:worker_threads</code> also restarts the run, including scripts outside the project and in excluded directories such as <code>dist</code>. This holds whoever starts the worker, so a dependency that starts one on a missing path outside <code>node_modules</code> is watched for that path too. Scripts under <code>node_modules</code> remain excluded.</p><p>A dependency borrowing an application&#39;s cached module object through <code>require.main.require</code>, <code>module.parent.require</code>, an application-supplied <code>require</code>, or <code>Module._load(request, appModule)</code> has application attribution. Its failed targets are watched, including targets in ancestor directories. A dependency walking up to the filesystem root through such a borrowed module can therefore cause a recursive watch on <code>/</code> for a missing file there. Use the dependency&#39;s own <code>require</code> for dependency-owned configuration searches.</p><p>Failed <code>require.resolve</code> calls with <code>options.paths</code> record no watch inputs. Repairing a target outside the watched project through those search paths needs a manual restart.</p><p>Dependencies reached through <code>node_modules</code> are excluded. A missing target in a workspace package reached through a <code>node_modules</code> link needs a manual restart after repair. Once a workspace source loads through that link, Bento watches its canonical path outside <code>node_modules</code>.</p><p>Sources outside the project are watched by their resolved file paths. Retargeting a symlink outside the project so that it points at a different file, or renaming away the directory that contains a loaded external source and putting another in its place, needs a manual restart. Editing, replacing, or deleting the external file itself restarts the run. Inside the project, the whole directory is watched, so these changes restart there too. An external source first loaded after startup, such as by a dynamic import inside a request handler, is watched within about 200 ms of loading; an edit made in that window is picked up only with the next change.</p><p>A missing file that <code>tsconfig.json</code> extends can be repaired the same way: creating it restarts the run, even when its parent directories must also be created. This also works through directory symlinks and for a missing configuration package installed into the project&#39;s own <code>node_modules</code>. If Bento cannot watch an extended configuration, it warns once for that file and retries on later source changes.</p><p>Inside the project, Bento ignores what running or building the application writes, so requests that write to them do not cause restarts:</p><ul><li>dependencies and version control: <code>node_modules</code> and <code>.git</code>;</li><li>build output and caches: <code>dist</code>, <code>build</code>, <code>target</code>, <code>.cache</code>, and <code>coverage</code> directories, and <code>.DS_Store</code> files;</li><li>databases and SQLite side files: <code>*.db</code>, <code>*.sqlite</code>, <code>*.sqlite3</code>, <code>*-wal</code>, <code>*-shm</code>, and <code>*-journal</code>;</li><li>environment files: <code>.env</code> and <code>.env.*</code>, because a restart would not reload them.</li></ul><p>A module the script actually loads from one of those places, such as an entrypoint in <code>dist</code>, is still watched. Modules loaded from <code>node_modules</code> directories inside the project are excluded, as are modules in <code>node_modules</code> directories outside it. A <code>node_modules</code> ancestor above the project root does not exclude the project&#39;s own loaded files.</p><p>Edits within about a tenth of a second of each other cause one restart. Bento says on standard error which file changed each time it restarts. The new instance starts only after the old one has shut down, as it would for a termination signal, and released its port. When loading fails, Bento reports the error, says it is waiting for changes, and keeps watching, so fixing the file or creating the missing one recovers; it never keeps serving the old code as though the reload had worked. A script that ends by itself, by finishing its work or calling <code>process.exit</code>, does not end the watch either: Bento reports how it ended and runs it again after the next change.</p><p>When a run ends with work it started still unsettled at the shutdown deadline, Bento says that disposal is incomplete and keeps watching, instead of ending with status 1 as a plain <code>bento run</code> does. A restart whose shutdown leaves work unfinished is reported the same way.</p><p>Watching does not reload <code>.env</code> files and does not rerun the tasks that started it. When the guest book&#39;s <code>dev</code> task starts <code>bento run --watch server.ts</code>, migrations run once, before the watcher starts. <code>--watch</code> selects the <code>development</code> mode for the environment files and <code>NODE_ENV</code> unless your environment or <code>.env</code> sets <code>NODE_ENV</code>.</p><p>Stopping the command stops both the application and the watching. Ctrl-C or a termination signal stops the running script as <a href="#stop-a-run">Stop a run</a> describes, and then <code>bento</code> exits instead of waiting for changes. When no script is running, because loading failed or the script ended by itself, <code>bento</code> exits at once with <code>130</code> or <code>143</code>. A nested <code>bento run --watch</code> that a task started stops the same way when you stop the outer <code>bento</code>.</p><p><code>--watch</code> applies to scripts only. <code>bento run --watch &lt;task-name&gt;</code> is an error; declare a task whose command runs <code>bento run --watch &lt;script&gt;</code>, as the guest book&#39;s <code>dev</code> task does.</p><h3 id="install-dependencies" tabindex="-1">Install dependencies <a class="header-anchor" href="#install-dependencies" aria-label="Permalink to “Install dependencies”">​</a></h3><p><code>bento install</code> runs <code>pnpm install</code> in the project root, including <code>devDependencies</code>. <code>bento install --frozen-lockfile</code> reproduces the locked graph exactly and fails, without touching <code>pnpm-lock.yaml</code>, when it disagrees with <code>package.json</code>. <a href="./installing-dependencies">Installing Dependencies</a> covers the details.</p><h3 id="stop-a-run" tabindex="-1">Stop a run <a class="header-anchor" href="#stop-a-run" aria-label="Permalink to “Stop a run”">​</a></h3><p>When you press Ctrl-C or send <code>bento</code> a termination signal while a task runs, Bento forwards the signal to the task command&#39;s whole process group, including servers started by nested <code>bento</code> commands. Processes still running after a 10-second grace period are killed. <code>bento</code> exits once nothing from the task is left running, so its port is free again. It prints that the task was cancelled and exits with the status the command ended with, as a shell reports it: <code>0</code> when the command handles the signal and exits cleanly, as a nested <code>bento</code> does when its script&#39;s listener closes the script, and <code>130</code> or <code>143</code> when the signal ends it. When Bento had to kill anything in the group, it exits with <code>130</code> or <code>143</code>. The same holds while Bento is stopping processes a finished command left running in the background: the signal reaches them too, and <code>bento</code> exits with <code>130</code> or <code>143</code> rather than the command&#39;s own status.</p><p>When <code>bento</code> runs a script, the first Ctrl-C or termination signal goes to the script, which then has five seconds to end:</p><ul><li>If the script listens for that signal with <code>process.on(&quot;SIGINT&quot;)</code> or <code>process.on(&quot;SIGTERM&quot;)</code>, its listeners run and decide what happens, as under Node. When the script then ends, by closing its servers and calling <code>process.exit(code)</code> or by running out of work, <code>bento</code> exits with the script&#39;s code.</li><li>Without a listener, Bento shuts the script down: it closes the script&#39;s servers and their connections and cancels its pending work. A <code>process.on(&quot;SIGTERM&quot;)</code> listener is told first, so a script that listens only for termination still cleans up after Ctrl-C. When Bento ends the script, <code>bento</code> exits with <code>130</code> for an interrupt or <code>143</code> for a termination signal. When the script ends itself first, for example by calling <code>process.exit(code)</code> from its termination listener, <code>bento</code> exits with the script&#39;s code, <code>0</code> included.</li></ul><p>A script still running five seconds after the signal is stopped then, whether its listeners have not finished or its JavaScript never yields, as in an endless loop. <code>bento</code> exits with <code>130</code> or <code>143</code>, and the script&#39;s port is freed with it. A listener that throws is reported like any uncaught exception, and <code>bento</code> exits with <code>1</code>.</p><p>A second Ctrl-C or termination signal does not wait: <code>bento</code> exits immediately with <code>130</code> or <code>143</code>, and its port is freed with it.</p><h3 id="exit-codes" tabindex="-1">Exit codes <a class="header-anchor" href="#exit-codes" aria-label="Permalink to “Exit codes”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>When</th></tr></thead><tbody><tr><td><code>0</code></td><td>The script or task finished successfully.</td></tr><tr><td>The script&#39;s code</td><td>The script called <code>process.exit(code)</code> before the deadline, including from a signal listener or while Bento shut it down.</td></tr><tr><td>The command&#39;s code</td><td>A task command failed, or ended after Bento forwarded a signal to it; a command killed by signal <code>N</code> gives <code>128 + N</code>, as shells report it.</td></tr><tr><td>pnpm&#39;s code</td><td><code>pnpm install</code> failed.</td></tr><tr><td><code>130</code></td><td>An interrupt (SIGINT, Ctrl-C) stopped the run: a task command it ended or that Bento had to kill, processes a finished task command left running, a script without a listener for it, or a script still running at the deadline or interrupted a second time.</td></tr><tr><td><code>143</code></td><td>A termination signal (SIGTERM) stopped the run, in the same cases.</td></tr><tr><td><code>1</code></td><td>Any other failure, reported with a message: an unknown target, a usage error such as a malformed permission flag, an <code>--allow-*</code> flag without <code>--permission</code>, or a nested flag beyond its ceiling, a malformed environment file, an invalid task graph, misplaced arguments, or a script that failed to start, could not load a module, was denied a permission, threw an uncaught exception, or ended while work it started had not settled.</td></tr></tbody></table><h2 id="worked-example" tabindex="-1">Worked example <a class="header-anchor" href="#worked-example" aria-label="Permalink to “Worked example”">​</a></h2><p>The guest book runs like any Node project, with no flags:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;">cd</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> fixtures/remix-guest-book</span></span>
<span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">bento</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> install</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">bento</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> run</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> dev</span></span></code></pre></div><p>To contain it instead, restrict the launch to what the guest book uses: reading files, writing its database directory, the network, three variables, and the native compilers installed in <code>node_modules</code>:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">bento</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> run</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --permission</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --allow-fs-read=</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;">&#39;*&#39;</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --allow-fs-write=./db</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --allow-net</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --allow-env=PORT,DATABASE_URL,NODE_ENV</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --allow-addons</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> dev</span></span></code></pre></div><p>Reading is not limited to the project because <code>remix/assets</code> looks for optional packages in the <code>node_modules</code> directory of every ancestor of the project, up to <code>/</code>, as Node&#39;s package lookup does. With only <code>--allow-fs-read=.</code>, that lookup is denied and the server does not start. The guest book&#39;s <code>db</code> directory exists, so <code>--allow-fs-write=./db</code> covers the database and its journal files beneath it.</p><p><code>bento run ... dev</code> runs the <code>db:migrate</code> task once, then the <code>dev</code> command <code>bento run --watch server.ts</code>. That nested launch passes no <code>--permission</code>, so it holds exactly the permissions above. Editing a file under <code>app/</code>, whether a module the server imports or a browser module under a <code>public/</code> directory, restarts the server without rerunning the migrations; saving entries, which writes the database, does not. Ctrl-C reaches the guest book&#39;s own <code>SIGINT</code> listener through the nested <code>bento</code>, which closes its server and database and exits with <code>0</code>; both <code>bento</code> processes then exit with <code>0</code>. Running <code>bento run ... server.ts</code> with the same flags instead, Ctrl-C reaches the same listener, and <code>bento</code> exits with <code>0</code> too.</p><p><code>dev</code> itself selects no mode, so it and its <code>db:migrate</code> task read only <code>.env</code>; only the nested watch launch also reads <code>.env.development</code>. When <code>.env.development</code> alone sets <code>DATABASE_URL</code>, migrate that database first with <code>NODE_ENV=development bento run db:migrate</code>, as the guest book&#39;s README shows.</p><p>If a task in the same project ran <code>bento run --permission --allow-fs-write=. server.ts</code> under those permissions, the nested launch would stop before running anything, because the project directory is more than the inherited <code>./db</code>:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>error: --allow-fs-write=/Users/you/guest-book/* asks for more than the inherited fs-write permission: /Users/you/guest-book/db/*</span></span></code></pre></div><p>The error shows both values as resolved patterns: an existing directory appears as <code>directory/*</code>, because it covers everything beneath it.</p><h2 id="limits-and-edge-cases" tabindex="-1">Limits and edge cases <a class="header-anchor" href="#limits-and-edge-cases" aria-label="Permalink to “Limits and edge cases”">​</a></h2><ul><li>Bento options after the target are not Bento options. They belong to the script, or make a task invocation fail because they come without <code>--</code>.</li><li>A cancelled task stops at the command the signal reached, even when that command handles the signal and exits with <code>0</code>; its later commands and the tasks that depend on it do not run.</li><li>Bento needs every environment variable it starts with to be valid UTF-8, and reports the first one that is not.</li><li>Permissions restrict guest code, not task commands. A task is a trusted operation on your behalf, and its commands run with your user&#39;s full authority.</li><li>A restricted launch is application policy, not a sandbox. Subprocesses it is allowed to start and native addons it is allowed to load run outside every permission, as in Node.</li><li><code>fork()</code>, and code that starts <code>process.execPath</code> with Node&#39;s options, fails until Bento accepts Node&#39;s command line (<a href="https://github.com/bento-js/bento/issues/260" target="_blank" rel="noreferrer">#260</a>).</li><li>Bento has no audit mode (<code>--permission-audit</code>, <a href="https://github.com/bento-js/bento/issues/261" target="_blank" rel="noreferrer">#261</a>), does not read permissions from Node&#39;s configuration files (<a href="https://github.com/bento-js/bento/issues/262" target="_blank" rel="noreferrer">#262</a>), and has no <code>--deny-*</code> flags, as Node has none. <code>--allow-child-process</code> allows every command; neither Bento nor Node 26 can limit it to particular ones.</li><li>A <code>BENTO_PERMISSION_CEILING</code> that Bento cannot read stops the launch instead of allowing anything. Bento sets it for task commands and for processes a restricted guest starts; you do not set it yourself.</li></ul>`,125)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};